use ao_reason_workbench::{config::{Actor,NodeSpec},core::{store::Store,runner::Runner,project_work::*},adapters::{AoPort,WorkRequest,Observation}};
use sha2::{Digest,Sha256};
use serde_json::json;
fn work()->ProjectWork{let text="# 已确认需求\n实现订单库存扣减和退款补偿。\n".to_owned();ProjectWork{schema:"project-work/1".into(),project_id:"project-1".into(),action_id:"action-1".into(),stage:ProjectStage::Split,document:ConfirmedDocument{version:1,sha256:hex::encode(Sha256::digest(text.as_bytes())),text},tasks:vec![],target_task:None,repair_reason:None,repair_round:0,test_spec:None,artifact:None}}
fn node()->NodeSpec{NodeSpec{id:"B".into(),address:"owned-B/runner".into(),key_hex:"07".repeat(32),slots:1,admitted:true,healthy:true,draining:false,templates:vec!["project-work-v1".into()]}}
#[test]
fn structured_document_dispatch_is_durable_and_reaches_exact_runner_request(){let t=tempfile::tempdir().unwrap();let w=work();let mut c=Store::open(&t.path().join("c.db"),"project-native",&[node()]).expect("project template is supported");let actor=Actor::Local("trusted-host".into());let run=c.dispatch_project(&actor,&w,100).expect("actual document work is queued");drop(c);let mut c=Store::open(&t.path().join("c.db"),"project-native",&[node()]).unwrap();assert_eq!(c.run(&run.id).unwrap().detail["project_work"],serde_json::to_value(&w).unwrap());c.assign_next(100).unwrap().unwrap();let (_,m)=c.pending_outbox(1).unwrap().remove(0);assert_eq!(m.payload["project_work"]["document"]["text"],w.document.text);m.verify(&hex::decode(node().key_hex).unwrap(),"project-native","B",100).unwrap();let mut r=Runner::open(&t.path().join("r.db"),"project-native",node()).unwrap();r.accept(&m,100).unwrap();drop(r);let mut r=Runner::open(&t.path().join("r.db"),"project-native",node()).unwrap();struct Capture{seen:Vec<ProjectWork>}impl AoPort for Capture{fn create(&mut self,r:&WorkRequest)->anyhow::Result<String>{self.seen.push(r.project_work.clone().expect("exact structured work"));Ok("owned-worker".into())}fn observe(&mut self,_:&str)->anyhow::Result<Observation>{Ok(Observation::Running)}fn resolve(&mut self,_:&str,_:&str,_:&str)->anyhow::Result<()>{unreachable!()}fn kill(&mut self,_:&str)->anyhow::Result<()>{unreachable!()}}let mut ao=Capture{seen:vec![]};r.tick(&mut ao,100).unwrap();r.tick(&mut ao,100).unwrap();assert_eq!(ao.seen,vec![w]);assert!(!c.assignment(&run.id,1).unwrap().unwrap().released);}
#[test]
fn execution_preflight_counts_serialized_utf8_and_rejects_without_queue_or_slot(){let t=tempfile::tempdir().unwrap();let mut c=Store::open(&t.path().join("c.db"),"project-native",&[node()]).unwrap();let mut w=work();w.document.text="中\n\"".repeat(20_000);w.document.sha256=hex::encode(Sha256::digest(w.document.text.as_bytes()));assert!(w.document.text.len()<256*1024);assert!(c.dispatch_project(&Actor::Local("host".into()),&w,100).is_err());assert!(c.list_runs(10).unwrap().is_empty());assert_eq!(c.outbox_count().unwrap(),0);}
#[test]
fn document_hash_and_manual_development_gate_are_checked_before_dispatch(){let mut w=work();w.validate().expect("valid confirmed document");w.document.sha256="00".repeat(32);assert!(w.validate().is_err());let mut w=work();w.stage=ProjectStage::Develop;assert!(w.validate().is_err());w.tasks=vec![WorkTask{id:"task-1".into(),title:"库存".into(),description:"原子扣减".into(),acceptance:"库存不为负".into(),depends_on:vec![],review:"approved".into(),reason:None}];let spec="库存边界和退款补偿验收".to_owned();w.test_spec=Some(FrozenInput{sha256:hex::encode(Sha256::digest(spec.as_bytes())),text:spec});w.validate().expect("explicit approved tasks and frozen test spec");w.tasks[0].review="pending".into();assert!(w.validate().is_err());}
#[test]
fn production_http_adapter_uses_fixed_stage_prompt_and_exact_document_data(){use std::io::{Read,Write};use ao_reason_workbench::{adapters::ao_http::AoHttp,config::AoConfig};let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let address=listener.local_addr().unwrap();let server=std::thread::spawn(move||{let end=std::time::Instant::now()+std::time::Duration::from_secs(3);let mut s=loop{match listener.accept(){Ok((s,_))=>break s,Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>{assert!(std::time::Instant::now()<end,"adapter did not send actual HTTP");std::thread::sleep(std::time::Duration::from_millis(5));},Err(e)=>panic!("{e}")}};s.set_nonblocking(false).unwrap();s.set_read_timeout(Some(std::time::Duration::from_secs(3))).unwrap();let mut header=Vec::new();loop{let mut b=[0];s.read_exact(&mut b).unwrap();header.push(b[0]);if header.ends_with(b"\r\n\r\n"){break}}let header=String::from_utf8(header).unwrap();let n:usize=header.lines().find_map(|l|l.to_ascii_lowercase().strip_prefix("content-length:").map(|n|n.trim().parse().unwrap())).unwrap();let mut body=vec![0;n];s.read_exact(&mut body).unwrap();let reply=json!({"session":{"id":"actual-doc-worker","kind":"worker","harness":"claude-code"}}).to_string();write!(s,"HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",reply.len(),reply).unwrap();serde_json::from_slice::<serde_json::Value>(&body).unwrap()});let w=work();let mut ao=AoHttp::new(AoConfig{base_url:format!("http://{address}"),project_id:"owned-project".into(),model:"claude-opus-5-5".into()}).unwrap();let result=ao.create(&WorkRequest{run_id:"run-1".into(),attempt:1,epoch:"epoch-1".into(),template:"project-work-v1".into(),session:"request-1".into(),project_work:Some(w.clone())});let request=server.join().unwrap();assert_eq!(result.unwrap(),"actual-doc-worker");let prompt=request["prompt"].as_str().unwrap();let data:serde_json::Value=serde_json::from_str(prompt.split_once("\nPROJECT_WORK_JSON\n").unwrap().1).unwrap();assert_eq!(data,serde_json::to_value(w).unwrap());assert!(!prompt.contains("sum_values"));assert!(prompt.contains("project-result.json"));}
